```json
{
  "predictors": [
    {
      "name": "Earnings Revision Velocity",
      "construction": "Calculate the percentage change in analyst earnings estimates for the next fiscal year over the past month.",
      "rationale": "Rapid upward revisions may indicate new favorable information leading to increased investor interest.",
      "higher_returns_for": "stocks with high positive changes in earnings estimates"
    },
    {
      "name": "Supply Chain Integration",
      "construction": "Ratio of a firm's accounts payable to the accounts receivable of its top suppliers, averaged over the last fiscal year.",
      "rationale": "Firms effectively managing their supply chains may achieve cost efficiencies and stronger pricing power.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Marketing Intensity",
      "construction": "Advertising expenses divided by total sales, averaged over the past three fiscal years.",
      "rationale": "Firms investing heavily in marketing may build stronger brands, leading to increased market share and pricing power.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Technology Adoption Index",
      "construction": "Ratio of capital expenditures on technology to total capital expenditures, calculated annually.",
      "rationale": "Firms investing more in technology may realize productivity gains and competitive advantages.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Environmental Efficiency",
      "construction": "Ratio of waste management expenses to total revenue, averaged over the last fiscal year.",
      "rationale": "Firms effectively managing environmental costs may reduce regulatory risks and improve operational efficiency.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Global Market Integration",
      "construction": "Proportion of total revenue derived from international sales, calculated annually.",
      "rationale": "Firms with significant global operations may benefit from diversified revenue sources and currency advantages.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Employee Training Investment",
      "construction": "Training expenses divided by the number of employees, averaged over the past two years.",
      "rationale": "Investing in employee skill development may enhance productivity and innovation.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Product Diversification Index",
      "construction": "Count of distinct product lines offered by the firm, updated annually.",
      "rationale": "Firms with a broad product portfolio may better withstand market fluctuations and capture diverse customer segments.",
      "higher_returns_for": "high values of the measure"
    },
    {
      "name": "Customer Concentration",
      "construction": "Percentage of total sales to the firm's top customer, reported in the latest fiscal year.",
      "rationale": "High dependency on a single customer may increase business risk, potentially affecting stability and growth.",
      "higher_returns_for": "low values of the measure"
    },
    {
      "name": "Executive Compensation Performance Sensitivity",
      "construction": "CEO compensation tied to performance metrics divided by total CEO compensation, recalculated annually.",
      "rationale": "Performance-linked compensation structures may align management's interests with shareholders, driving value creation.",
      "higher_returns_for": "high values of the measure"
    }
  ]
}
